import hmac, hashlib, base64, json, time

def _b64(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).rstrip(b'=').decode()

def _b64d(s: str) -> bytes:
    return base64.urlsafe_b64decode(s + '=' * (-len(s) % 4))

def create_access_token(payload: dict, secret: str) -> str:
    header = {"alg": "HS256", "typ": "JWT"}
    now = int(time.time())
    body = {**payload, "iat": now, "exp": now + 7 * 60}
    h = _b64(json.dumps(header, separators=(',', ':')).encode())
    p = _b64(json.dumps(body, separators=(',', ':')).encode())
    signing_input = f"{h}.{p}".encode()
    sig = _b64(hmac.new(secret.encode(), signing_input, hashlib.sha256).digest())
    return f"{h}.{p}.{sig}"

def verify_access_token(token: str, secret: str) -> dict:
    try:
        h, p, sig = token.split('.')
    except ValueError:
        raise ValueError("malformed token")
    expected = _b64(hmac.new(secret.encode(), f"{h}.{p}".encode(), hashlib.sha256).digest())
    if not hmac.compare_digest(sig, expected):
        raise ValueError("invalid signature")
    body = json.loads(_b64d(p))
    if body.get("exp", 0) < int(time.time()):
        raise ValueError("token expired")
    return body
